def upstream_stations(n, pipes, r):
    back = [[] for _ in range(n)]
    for a, b in pipes:
        back[b].append(a)
    seen = [False] * n
    seen[r] = True
    stack = [r]
    while stack:
        x = stack.pop()
        for y in back[x]:
            if not seen[y]:
                seen[y] = True
                stack.append(y)
    return [v for v in range(n) if seen[v] and v != r]
